/**
 * Team Helios brand. These are the app's only brand marks (no NASA insignia).
 * Source art: public/brand/*.svg, generated by scripts/brand/outline-text.mjs.
 */

/** Icon only: the sun, its rays and the orbit with the satellite dot. Decorative by default. */
export function HeliosMark({ size = 44, title }: { size?: number; title?: string }) {
  return (
    <img
      src="/brand/helios-mark.svg"
      width={size}
      height={size}
      alt={title ?? ''}
      aria-hidden={title ? undefined : true}
      draggable={false}
      className="block select-none"
    />
  );
}

/** "HEL☀OS" wordmark with the orbit. Letters are outlined paths, so it needs no font. */
export function HeliosWordmark({ width = 120, variant = 'primary', title }: { width?: number; variant?: 'primary' | 'mono' | 'dark'; title?: string }) {
  const file = variant === 'primary' ? 'helios-wordmark' : `helios-wordmark-${variant}`;
  return (
    <img
      src={`/brand/${file}.svg`}
      width={width}
      height={Math.round((width * 90) / 300)}
      alt={title ?? ''}
      aria-hidden={title ? undefined : true}
      draggable={false}
      className="block select-none"
    />
  );
}
